export const ATTRIBUTE_SCALE={VIG:{for:.8,int:.1,des:2,magic:.3},ESP:{for:1.2,int:.1,des:1.7,magic:.3},ARC:{for:.2,int:0,des:.1,magic:3.2},BAS:{for:2.2,int:.1,des:.3,magic:.4},RUP:{for:2.8,int:.1,des:.4,magic:.3},DUE:{for:1.8,int:.1,des:1.4,magic:.3},LAS:{for:2,int:0,des:.8,magic:2.8}};
export function totalPoints(value){const p=typeof value==='object'?value:null,level=p?p.level:value;return Math.max(0,Math.min(999,Math.floor(level)-1))*5+(p?Math.max(0,p.rebirth?.bankedLevelPoints||0)+Math.max(0,Math.floor(p.rebirth?.count||0))*500:0);}
export function usedPoints(a={}){return ['for','int','des'].reduce((sum,k)=>sum+Math.max(0,Math.floor(Number(a[k])||0)),0);}
export function validAllocation(level,a){return Object.keys(a).every(k=>['for','int','des'].includes(k)&&Number.isInteger(a[k])&&a[k]>=0)&&usedPoints(a)<=totalPoints(level);}
export function attributeGains(p){const a={for:0,int:0,des:0,...p.attributes},scale=ATTRIBUTE_SCALE[p.classId];if(!validAllocation(p,a))return attributeGains({...p,attributes:{for:0,int:0,des:0}});const physical=a.for*scale.for+a.des*scale.des,magical=a.int*scale.magic;return {attack:p.classId==='ARC'?magical:p.classId==='LAS'?.65*physical+.35*magical:physical,physical,magical,def:(a.for+a.int)*.3,mp:a.int*4,accuracy:a.des*3,evasion:a.des*2,hpPct:Math.floor(a.for/25)*.005,mpPct:Math.floor(a.int/25)*.005,crit:Math.floor(a.des/25)*.0025,haste:Math.floor(a.des/50)*.005,critd:Math.floor(a.for/50)*.01,magicAmp:Math.floor(a.int/50)*.01};}
